parameters.jsCode:
// Phân loại nguồn thành 2 tầng:
//  PRIMARY   = nhà nước / học thuật / peer-reviewed — được dùng LÀM NGUỒN SỐ LIỆU và được link
//  SECONDARY = tổ chức y tế / y khoa uy tín — CHỈ được link, CẤM dùng làm nguồn số liệu dinh dưỡng
//  competitor= còn lại — không link, chỉ để nghiên cứu cấu trúc

const PRIMARY = [
  /\.gov(\/|$|:)/, /\.gov\./, /\.edu(\/|$|:)/,
  /usda\.gov/, /nal\.usda/, /fdc\.nal/, /nih\.gov/, /ncbi\.nlm\.nih\.gov/,
  /pubmed/, /pmc\.ncbi/, /who\.int/, /fda\.gov/, /efsa\.europa\.eu/,
  /fao\.org/, /cdc\.gov/, /extension\.[a-z]+\.edu/, /foodsafety\.gov/,
  /sciencedirect\.com/, /nature\.com/, /bmj\.com/, /thelancet\.com/,
  /cochrane/, /springer/, /wiley\.com/, /mdpi\.com/, /frontiersin\.org/,
];

const SECONDARY = [
  /mayoclinic\.org/, /clevelandclinic\.org/, /hopkinsmedicine\.org/,
  /health\.harvard\.edu/, /heart\.org/, /diabetes\.org/, /eatright\.org/,
  /healthline\.com/, /webmd\.com/, /medicalnewstoday\.com/,
  /nhs\.uk/, /betterhealth\.vic\.gov\.au/, /vinmec\.com/,
];

const results = $input.first().json.results || [];

const cleaned = results.map(r => {
  const url = String(r.url || '').toLowerCase();
  const tier = PRIMARY.some(re => re.test(url))
    ? 'PRIMARY'
    : SECONDARY.some(re => re.test(url)) ? 'SECONDARY' : 'competitor';
  return {
    title: r.title || '',
    url: String(r.url || ''),
    content: r.content || '',
    raw: r.raw_content || '',
    tier,
  };
});

// Danh sách snippet cho outline/fact-check
const list = cleaned.map((r, i) =>
  `${i + 1}. ${r.title}\nURL: ${r.url}\n${r.content}\n`
).join('\n---\n');

// raw_content: ưu tiên PRIMARY > SECONDARY > còn lại
const rank = { PRIMARY: 0, SECONDARY: 1, competitor: 2 };
const withRaw = cleaned.filter(r => r.raw).sort((a, b) => rank[a.tier] - rank[b.tier]);
const rawExcerpts = withRaw.slice(0, 3).map((r, i) =>
  `SOURCE ${i + 1} [${r.tier}]: ${r.title}\nURL: ${r.url}\n${String(r.raw).slice(0, 4000)}`
).join('\n\n=====\n\n');

const sourcesList = cleaned.map((r, i) =>
  `${i + 1}. [${r.tier}] ${r.title} — ${r.url}`
).join('\n');

return [{
  json: {
    total: cleaned.length,
    primary_count: cleaned.filter(r => r.tier === 'PRIMARY').length,
    secondary_count: cleaned.filter(r => r.tier === 'SECONDARY').length,
    list,
    raw_excerpts: rawExcerpts || 'No raw excerpts available — write qualitatively and do not invent numbers.',
    sources_list: sourcesList,
  }
}];

