parameters.jsCode:
// Gộp output của AI Agent (title+outline+entity) và AI Agent1 (conflict+eeat)
const items = $input.all();

if (items.length < 2) {
  throw new Error(`Merge chỉ nhận được ${items.length} item — cần đúng 2 (từ AI Agent và AI Agent1). Kiểm tra lại node Merge phía trước.`);
}

const a = items[0]?.json?.output ?? items[0]?.json ?? {};
const b = items[1]?.json?.output ?? items[1]?.json ?? {};

// Title: ưu tiên title do outline agent quyết (đã tôn trọng Title trong sheet nếu có),
// fallback về Title gốc trong sheet nếu agent không trả về
const sheetTitle = $('Get row(s) in sheet1').first().json.Title || '';
const title = a.title || b.title || sheetTitle;

if (!title) {
  throw new Error('Không có title — outline agent không trả về title và cột Title trong sheet cũng trống.');
}

return [{
  json: {
    title,
    outline: a.outline || b.outline || [],
    entities: a.entities || b.entities || [],
    conflicts: b.conflicts || a.conflicts || [],
    eeat_angle: b.eeat_angle || a.eeat_angle || {},
  }
}];

// Gộp HTML + Meta, chuẩn hóa ký tự, chèn block E-E-A-T, JSON-LD schema và QA audit
const items = $input.all();

if (items.length < 2) {
  throw new Error(`Merge2 chỉ nhận được ${items.length} item — cần đúng 2 (từ Markdown to HTML và AI Agent Meta).`);
}

const htmlItem = items.find(i => typeof i.json.output === 'string');
const metaItem = items.find(i => i.json.output && typeof i.json.output === 'object');

let html = htmlItem?.json?.output || '';
const meta = metaItem?.json?.output || {};

const chosenTitle = $('Code in JavaScript7').first().json.title || meta.title_seo || '';

// 1. Chuẩn hóa ký tự + bỏ prefix Q:/A: hiển thị trong FAQ
html = html
  .replace(/\u2011/g, '-')
  .replace(/\u00A0/g, ' ')
  .replace(/<h3>Q:\s*/g, '<h3>')
  .replace(/<p>A:\s*/g, '<p>');

// 2. Thông tin tác giả từ sheet
const row = $('Get row(s) in sheet1').first().json || {};
const author = row.Author || row.author || 'TMICORP Editorial Team';
const reviewer = row.Reviewer || row.reviewer || '';
const today = new Date().toISOString().slice(0, 10);

// 3. Phát hiện YMYL
const ymylHint = String(row.is_ymyl || row.YMYL || '').toLowerCase().trim();
const isYmyl = ymylHint
  ? ['1', 'yes', 'true', 'y', 'x'].includes(ymylHint)
  : /\b(health benefit|nutrition|nutrient|diabet|pregnan|calorie|vitamin|blood sugar|allerg)\w*/i.test(html);

const eeatTop =
  `<div class="post-meta"><p><strong>By ${author}</strong>` +
  (reviewer ? ` | Reviewed by ${reviewer}` : '') +
  ` | Last updated: ${today}</p></div>`;

const disclaimer = isYmyl
  ? `<div class="disclaimer"><p><em>This article is for general informational purposes only and is not medical advice. Consult a qualified healthcare professional for guidance on your individual situation.</em></p></div>`
  : '';

const warn = [];

// 4. AUDIT CITATION — cap 2 link/domain, tối thiểu 2 domain
const domainCounts = {};
for (const m of html.matchAll(/href="https?:\/\/([^\/"?]+)/g)) {
  const d = m[1].replace(/^www\./, '').toLowerCase();
  domainCounts[d] = (domainCounts[d] || 0) + 1;
}
const domainList = Object.keys(domainCounts);
const overCap = Object.entries(domainCounts).filter(([, c]) => c > 2).map(([d, c]) => `${d}(${c})`);
if (overCap.length) warn.push(`Vượt cap 2 link/domain: ${overCap.join(', ')}`);
if (domainList.length < 2) warn.push(`Chỉ có ${domainList.length} domain — cần tối thiểu 2`);

// 5. AUDIT ANCHOR TEXT chung chung
const badAnchors = [];
for (const m of html.matchAll(/<a [^>]*>([^<]+)<\/a>/g)) {
  const t = m[1].trim();
  if (/^(study link|click here|here|source|link|read more|https?:)/i.test(t)) badAnchors.push(t);
}
if (badAnchors.length) warn.push(`Anchor text chung chung: ${badAnchors.join(', ')}`);

// 6. AUDIT USDA
const usdaTable = $('Format USDA Nutrition').first().json.usda_table;
if (usdaTable) {
  if (!/href="[^"]*fdc\.nal\.usda\.gov/i.test(html)) warn.push('Có dữ liệu USDA nhưng bài không dẫn LINK USDA (có thể đang ở dạng URL trần)');
  if (!/<table/i.test(html)) warn.push('Có dữ liệu USDA nhưng bài không có bảng dinh dưỡng');
}

// 7. AUDIT HEADING — phát hiện chỉ dẫn nội bộ lọt vào tiêu đề
const KEYWORDY = /\((?:render|use|using|target|insert|include|add|note|format|framing|keyword|placement|angle|H[123])\b[^)]*\)|\([^)]*\b(?:framing|render|keyword|placement)\b[^)]*\)/i;
const dirtyHeadings = [];
for (const m of html.matchAll(/<h[23]>([^<]+)<\/h[23]>/g)) {
  const h = m[1].trim();
  let dirty = KEYWORDY.test(h);
  if (!dirty) {
    for (const p of h.matchAll(/\(([^)]+)\)/g)) {
      if (p[1].trim().split(/\s+/).length >= 3) { dirty = true; break; }
    }
  }
  if (dirty) dirtyHeadings.push(h);
}
if (dirtyHeadings.length) warn.push(`Heading có chỉ dẫn/keyword lọt: ${dirtyHeadings.join(' | ')}`);

// 8. JSON-LD: Article + FAQPage
const faqs = [];
for (const m of html.matchAll(/<h3>([^<]*\?)<\/h3>\s*<p>([^<]+)<\/p>/g)) {
  faqs.push({ q: m[1].trim(), a: m[2].trim() });
}
if (faqs.length === 0) warn.push('Không tìm thấy FAQ — thiếu FAQPage schema');

const org = {
  '@type': 'Organization',
  name: 'TMICORP - Toan My International Trading Investment JSC.',
  address: { '@type': 'PostalAddress', addressLocality: 'Hanoi', addressCountry: 'VN' },
  hasCredential: ['ISO 22000', 'HACCP', 'FDA registered', 'BRC FOOD', 'HALAL'].map(c => ({
    '@type': 'EducationalOccupationalCredential', name: c
  })),
};

const ld = [{
  '@context': 'https://schema.org',
  '@type': 'Article',
  headline: meta.title_seo || chosenTitle,
  description: meta.meta_description || '',
  datePublished: today,
  dateModified: today,
  author: reviewer
    ? [{ '@type': 'Person', name: author }, { '@type': 'Person', name: reviewer, jobTitle: 'Reviewer' }]
    : { '@type': 'Organization', name: author },
  publisher: org,
}];

if (faqs.length > 0) {
  ld.push({
    '@context': 'https://schema.org',
    '@type': 'FAQPage',
    mainEntity: faqs.map(f => ({
      '@type': 'Question',
      name: f.q,
      acceptedAnswer: { '@type': 'Answer', text: f.a },
    })),
  });
}

const ldScript = `<script type="application/ld+json">${JSON.stringify(ld)}</script>`;
const finalHtml = eeatTop + '\n' + disclaimer + '\n' + html + '\n' + ldScript;

const wordCount = finalHtml.replace(/<script[\s\S]*?<\/script>/g, '').replace(/<[^>]*>/g, ' ').split(/\s+/).filter(Boolean).length;

return [{
  json: {
    html: finalHtml,
    chosen_title: chosenTitle,
    slug: meta.slug || '',
    title_seo: meta.title_seo || '',
    meta_description: meta.meta_description || '',
    tags: meta.tags || '',
    excerpt: meta.excerpt || '',
    word_count: wordCount,
    faq_count: faqs.length,
    is_ymyl: isYmyl,
    citation_domains: domainCounts,
    qa_warnings: warn.length ? warn.join(' | ') : 'OK',
  }
}];

