parameters.jsCode:
// Chuyển Markdown -> HTML deterministic (thay AI Agent HTML)
// Hỗ trợ: ##/###, **bold**, *italic*, [link](url), bảng, ul/ol, blockquote, đoạn văn

const md = String($input.first().json.output || '');

function inline(s) {
  return s
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/(^|[^*])\*([^*]+)\*/g, '$1<em>$2</em>')
    .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');
}

const lines = md.replace(/\r/g, '').split('\n');
const out = [];
let i = 0;

while (i < lines.length) {
  const line = lines[i];
  if (!line.trim()) { i++; continue; }

  if (/^### /.test(line)) { out.push(`<h3>${inline(line.slice(4).trim())}</h3>`); i++; continue; }
  if (/^## /.test(line))  { out.push(`<h2>${inline(line.slice(3).trim())}</h2>`); i++; continue; }

  if (/^> /.test(line)) {
    const buf = [];
    while (i < lines.length && /^> ?/.test(lines[i]) && lines[i].trim()) { buf.push(lines[i].replace(/^> ?/, '')); i++; }
    out.push(`<blockquote><p>${inline(buf.join(' '))}</p></blockquote>`);
    continue;
  }

  // Bảng markdown: | a | b | + dòng phân cách |---|---|
  if (/^\|.*\|\s*$/.test(line) && i + 1 < lines.length && /^\|[\s:|-]+\|\s*$/.test(lines[i + 1])) {
    const parseRow = l => l.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map(c => c.trim());
    const header = parseRow(line);
    i += 2;
    const rows = [];
    while (i < lines.length && /^\|.*\|\s*$/.test(lines[i])) { rows.push(parseRow(lines[i])); i++; }
    let t = '<table><thead><tr>' + header.map(h => `<th>${inline(h)}</th>`).join('') + '</tr></thead><tbody>';
    t += rows.map(r => '<tr>' + r.map(c => `<td>${inline(c)}</td>`).join('') + '</tr>').join('');
    t += '</tbody></table>';
    out.push(t);
    continue;
  }

  if (/^\d+\. /.test(line)) {
    const buf = [];
    while (i < lines.length && /^\d+\. /.test(lines[i])) { buf.push(lines[i].replace(/^\d+\. /, '')); i++; }
    out.push('<ol>' + buf.map(b => `<li>${inline(b)}</li>`).join('') + '</ol>');
    continue;
  }

  if (/^[-*] /.test(line)) {
    const buf = [];
    while (i < lines.length && /^[-*] /.test(lines[i])) { buf.push(lines[i].replace(/^[-*] /, '')); i++; }
    out.push('<ul>' + buf.map(b => `<li>${inline(b)}</li>`).join('') + '</ul>');
    continue;
  }

  // Đoạn văn: gom tới dòng trống hoặc block mới
  const buf = [line];
  i++;
  while (i < lines.length && lines[i].trim() && !/^(## |### |\||[-*] |\d+\. |> )/.test(lines[i])) {
    buf.push(lines[i]); i++;
  }
  out.push(`<p>${inline(buf.join(' ').trim())}</p>`);
}

return [{ json: { output: out.join('\n') } }];

// Chay MOT LAN CHO MOI ITEM.
// Row context lay tu Normalize Intent theo paired item -> khong con bug .first()
// Payload USDA lay tu $json (co the rong neu di nhanh No USDA)

const WANT = [
  ['Energy', 'Calories (kcal)'], ['Water', 'Water'], ['Protein', 'Protein'],
  ['Carbohydrate, by difference', 'Total carbohydrate'],
  ['Sugars, total including NLEA', 'Total sugars'],
  ['Fiber, total dietary', 'Dietary fiber'],
  ['Total lipid (fat)', 'Total fat'],
  ['Potassium, K', 'Potassium'], ['Calcium, Ca', 'Calcium'],
  ['Iron, Fe', 'Iron'], ['Magnesium, Mg', 'Magnesium'],
  ['Phosphorus, P', 'Phosphorus'], ['Sodium, Na', 'Sodium'],
  ['Zinc, Zn', 'Zinc'], ['Copper, Cu', 'Copper'], ['Manganese, Mn', 'Manganese'],
  ['Vitamin C, total ascorbic acid', 'Vitamin C'],
  ['Thiamin', 'Thiamin (B1)'], ['Riboflavin', 'Riboflavin (B2)'], ['Niacin', 'Niacin (B3)'],
];

const row = $('Normalize Intent').item.json;
const j = $json;

let usda_table = '', usda_source = '', usda_link = '', usda_food = '';
const nutrients = j.foodNutrients || [];

if (nutrients.length) {
  const byName = new Map();

  for (const n of nutrients) {
    // /food/{id} tra n.nutrient.name + n.amount
    // /foods/search tra n.nutrientName + n.value
    const name = n.nutrient?.name ?? n.nutrientName;
    const unit = String(n.nutrient?.unitName ?? n.unitName ?? '').toLowerCase();
    const val  = n.amount ?? n.value;

    if (!name || val === undefined || val === null) continue;

    // FIX: USDA tra ca kcal va kJ cho "Energy" - chi nhan kcal
    if (name === 'Energy' && unit !== 'kcal') continue;

    if (byName.has(name)) continue;
    byName.set(name, `${val} ${unit}`);
  }

  const lines = WANT.filter(([k]) => byName.has(k))
                    .map(([k, label]) => `| ${label} | ${byName.get(k)} |`);

  if (lines.length >= 5) {
    usda_food   = j.description || '';
    usda_source = `https://fdc.nal.usda.gov/food-details/${j.fdcId}/nutrients`;
    usda_link   = `[USDA FoodData Central](${usda_source})`;
    usda_table  = [
      `Nutrients per 100 g of ${usda_food} (USDA FoodData Central, FDC ID ${j.fdcId}):`,
      '',
      '| Nutrient | Per 100 g |',
      '|---|---|',
      ...lines,
      '',
      `Ready-to-use Markdown citation (paste exactly, never the bare URL): ${usda_link}`,
    ].join('\n');
  }
}

return { json: { ...row, usda_table, usda_source, usda_link, usda_food } };

const INTENT_MAP = [
  ['transactional', /transaction/i],
  ['commercial',    /commercial/i],
  ['navigational',  /navigat/i],
  ['informational', /informat/i],
];

const out = [];

for (const item of $input.all()) {
  const r = item.json;
  const raw = String(r['Search Intent'] ?? r.search_intent ?? r.intent ?? '').trim();

  let intent = '';
  for (const [name, re] of INTENT_MAP) {
    if (re.test(raw)) { intent = name; break; }
  }

  const primary = String(r.primary ?? '').trim();
  const seed    = String(r.Seed ?? r.seed ?? '').trim();

  if (!primary && !seed) {
    throw new Error(`Row ${r.row_number}: trong ca primary va Seed`);
  }
  if (!intent) {
    throw new Error(`Row ${r.row_number}: khong doc duoc Search Intent ("${raw}") - phai chua Information / Navigational / Commercial / Transactional`);
  }

  out.push({ json: {
    ...r,
    intent,
    intent_raw: raw,
    primary: primary || seed,
    seed: seed || primary,
  }});
}

return out;

