Primary keyword: {{ $json.primary }}
Product / seed: {{ $json.seed }}
Search intent: {{ $json.intent }}
Title: {{ $json.Title }}

parameters.jsCode:
// Gop N ket qua Tavily (moi query 1 item), nhom lai theo purpose.
// Ghep nguoc ve query bang INDEX: Tavily tra ra dung thu tu input.

const PRIMARY = [
  /\.gov(\/|$|:)/, /\.gov\./, /\.edu(\/|$|:)/, /\.nic\.in/, /\.ac\.in/,
  /fda\.gov/, /usda\.gov/, /nih\.gov/, /ncbi\.nlm\.nih\.gov/, /pubmed/,
  /who\.int/, /efsa\.europa\.eu/, /fao\.org/, /codexalimentarius/,
  /bfr\.bund\.de/, /ec\.europa\.eu/, /eur-lex\.europa\.eu/,
  // co quan quan ly An Do - quan trong khi target market la in
  /fssai\.gov\.in/, /indianspices\.com/, /spicesboard/, /icar\.org\.in/,
  /sciencedirect\.com/, /nature\.com/, /mdpi\.com/, /frontiersin\.org/,
  /cochrane/, /bmj\.com/, /thelancet\.com/,
];

// To chuc y te / y khoa uy tin: duoc LINK cho ngu canh suc khoe,
// nhung khong dung lam nguon so lieu neu co nguon PRIMARY
const HEALTH = [
  /mayoclinic\.org/, /clevelandclinic\.org/, /hopkinsmedicine\.org/,
  /health\.harvard\.edu/, /nhs\.uk/, /heart\.org/, /diabetes\.org/,
];

function tier(url) {
  const u = String(url || '').toLowerCase();
  if (PRIMARY.some(re => re.test(u))) return 'PRIMARY';
  if (HEALTH.some(re => re.test(u)))  return 'HEALTH';
  return 'competitor';
}

const plans   = $('Expand Queries C').all().map(i => i.json);
const results = $input.all();
const meta    = plans[0] || {};

if (results.length === 0) throw new Error('Search Web C khong tra ve item nao.');

const PURPOSES = ['serp', 'option', 'attribute', 'safety', 'price', 'local'];
const buckets = {};
PURPOSES.forEach(p => buckets[p] = []);
const queriesRun = [];

results.forEach((item, idx) => {
  const p = plans[idx] || {};
  const purpose = buckets[p.purpose] ? p.purpose : 'attribute';
  queriesRun.push(`[${purpose}] ${p.query || '(?)'}`);

  for (const r of (item.json?.results || [])) {
    buckets[purpose].push({
      title: r.title || '', url: String(r.url || ''),
      content: r.content || '', raw: r.raw_content || '', tier: tier(r.url),
    });
  }
});

if (buckets.serp.length === 0) {
  throw new Error('Query serp khong tra ve ket qua nao - kiem tra cot primary va Tavily trong sheet.');
}

// dedupe URL xuyen bucket
const seen = new Set();
for (const k of PURPOSES) {
  buckets[k] = buckets[k].filter(r => {
    const u = r.url.toLowerCase();
    if (!u || seen.has(u)) return false;
    seen.add(u); return true;
  });
}

const fmt = arr => arr.length
  ? arr.map((r, i) => `${i + 1}. [${r.tier}] ${r.title}\nURL: ${r.url}\n${r.content}\n`).join('\n---\n')
  : 'No results for this angle. Do NOT invent a figure to fill the gap.';

const rank = { PRIMARY: 0, HEALTH: 1, competitor: 2 };
const rawFrom = (arr, n) => arr.filter(r => r.raw)
  .sort((a, b) => rank[a.tier] - rank[b.tier]).slice(0, n)
  .map((r, i) => `SOURCE ${i + 1} [${r.tier}]: ${r.title}\nURL: ${r.url}\n${String(r.raw).slice(0, 4000)}`)
  .join('\n\n=====\n\n');

const optionData = [...buckets.option, ...buckets.attribute, ...buckets.local];
const all = PURPOSES.flatMap(p => buckets[p]);

return [{
  json: {
    ...meta,
    queries_run: queriesRun.join('\n'),
    serp_total:   buckets.serp.length,
