    serp_excerpts:   rawFrom(buckets.serp, 2) || 'No raw competitor excerpts available.',
    sources_list: all.map((r, i) => `${i + 1}. [${r.tier}] ${r.title} - ${r.url}`).join('\n'),
  }
}];

