// Markdown -> HTML deterministic cho nhanh Commercial.
// So voi ban goc: da THEM xu ly anh ![alt](url) va duong ke ---

const md = String($input.first().json.output || '');

function inline(s) {
  return s
    // anh PHAI xu ly TRUOC link, vi ![...](...) chua [...](...)
    .replace(/!\[([^\]]*)\]\(([^)\s]+)\)/g, '<img src="$2" alt="$1" loading="lazy">')
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/(^|[^*])\*([^*]+)\*/g, '$1<em>$2</em>')
    .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');
}

const lines = md.replace(/\r/g, '').split('\n');
const out = [];
let i = 0;

while (i < lines.length) {
  const line = lines[i];
  if (!line.trim()) { i++; continue; }

  // duong ke ngang: --- hoac *** (truoc khi coi la list)
  if (/^\s*([-*_])\s*\1\s*\1[\s\-*_]*$/.test(line)) { out.push('<hr>'); i++; continue; }

  if (/^### /.test(line)) { out.push(`<h3>${inline(line.slice(4).trim())}</h3>`); i++; continue; }
  if (/^## /.test(line))  { out.push(`<h2>${inline(line.slice(3).trim())}</h2>`); i++; continue; }

  if (/^> /.test(line)) {
    const buf = [];
    while (i < lines.length && /^> ?/.test(lines[i]) && lines[i].trim()) { buf.push(lines[i].replace(/^> ?/, '')); i++; }
    out.push(`<blockquote><p>${inline(buf.join(' '))}</p></blockquote>`);
    continue;
  }

  // bang markdown
  if (/^\|.*\|\s*$/.test(line) && i + 1 < lines.length && /^\|[\s:|-]+\|\s*$/.test(lines[i + 1])) {
    const parseRow = l => l.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map(c => c.trim());
    const header = parseRow(line);
    i += 2;
    const rows = [];
    while (i < lines.length && /^\|.*\|\s*$/.test(lines[i])) { rows.push(parseRow(lines[i])); i++; }
    let t = '<table><thead><tr>' + header.map(h => `<th>${inline(h)}</th>`).join('') + '</tr></thead><tbody>';
    t += rows.map(r => '<tr>' + r.map(c => `<td>${inline(c)}</td>`).join('') + '</tr>').join('');
    t += '</tbody></table>';
    out.push(t);
    continue;
  }

  if (/^\d+\. /.test(line)) {
    const buf = [];
    while (i < lines.length && /^\d+\. /.test(lines[i])) { buf.push(lines[i].replace(/^\d+\. /, '')); i++; }
    out.push('<ol>' + buf.map(b => `<li>${inline(b)}</li>`).join('') + '</ol>');
    continue;
  }

  if (/^[-*] /.test(line)) {
    const buf = [];
    while (i < lines.length && /^[-*] /.test(lines[i])) { buf.push(lines[i].replace(/^[-*] /, '')); i++; }
    out.push('<ul>' + buf.map(b => `<li>${inline(b)}</li>`).join('') + '</ul>');
    continue;
  }

  const buf = [line];
  i++;
  while (i < lines.length && lines[i].trim() && !/^(## |### |\||[-*] |\d+\. |> )/.test(lines[i])) {
    buf.push(lines[i]); i++;
  }
  out.push(`<p>${inline(buf.join(' ').trim())}</p>`);
}

return [{ json: { output: out.join('\n') } }];

