// Gop HTML + Meta, chen block tac gia, JSON-LD, QA audit cho bai
// COMMERCIAL B2C, doc gia TOAN CAU (khong nham quoc gia nao).

const items = $input.all();
if (items.length < 2) {
  throw new Error(`Merge Output C chi nhan duoc ${items.length} item - can dung 2 (MD to HTML C + Meta C).`);
}

const htmlItem = items.find(i => typeof i.json.output === 'string');
const metaItem = items.find(i => i.json.output && typeof i.json.output === 'object');

let html = htmlItem?.json?.output || '';
const meta = metaItem?.json?.output || {};

const brief = $('Code Brief C').first().json;
const chosenTitle = brief.title || meta.title_seo || '';
const today = new Date().toISOString().slice(0, 10);
const author = 'TMICORP Editorial Team';

html = html
  .replace(/\u2011/g, '-').replace(/\u00A0/g, ' ')
  .replace(/<h3>Q:\s*/g, '<h3>').replace(/<p>A:\s*/g, '<p>');

const warn = [];
const bodyOnly = html.replace(/<script[\s\S]*?<\/script>/g, '');
const text = bodyOnly.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ');
const low = text.toLowerCase();

// ---- 1. NHAM QUOC GIA (bai phai trung tinh thi truong) ----
const CURRENCY = /(\u20b9|\u00a3|\u20ac|\u00a5|\bINR\b|\bUSD\b|\bEUR\b|\bGBP\b|\bRs\.?\s?\d|\$\s?\d)/;
if (CURRENCY.test(text)) {
  warn.push('CO GIA THEO MOT LOAI TIEN TE - bai doc toan cau, phai dung muc gia tuong doi');
}
const NAT_AGENCY = ['fssai', 'fda', 'usda', 'food standards agency', 'anvisa', 'cfia', 'fsanz'];
const agencyHits = NAT_AGENCY.filter(a => new RegExp(`\\b${a}\\b`, 'i').test(text));
if (agencyHits.length) {
  warn.push(`DAN CO QUAN QUOC GIA: ${agencyHits.join(', ')} - dung tham chieu quoc te (EFSA, WHO, Codex, BfR) thay the`);
}
const RETAILERS = ['walmart', 'kroger', 'tesco', 'aldi', 'costco', 'bigbasket', 'amazon.in',
  'flipkart', 'target', 'sainsbury', 'carrefour', 'lidl', 'woolworths'];
const retailHits = RETAILERS.filter(r => new RegExp(r, 'i').test(low));
if (retailHits.length) warn.push(`NEU TEN CHUOI BAN LE: ${retailHits.join(', ')} - phai noi chung chung`);

const COUNTRY_HEAD = /(in|for) (india|the us|the united states|the uk|australia|canada|europe)\b/i;
for (const m of html.matchAll(/<h[23]>([^<]+)<\/h[23]>/g)) {
  if (COUNTRY_HEAD.test(m[1])) { warn.push(`Heading nham quoc gia: ${m[1].trim()}`); break; }
}

// ---- 2. B2B JARGON ----
const B2B = ['hs code', 'hs heading', 'moq', 'incoterm', ' fob ', 'per metric ton',
  'purchase order', 'iso 6571', 'iso 939', 'iso 928', 'iso 930', 'iso 948',
  'asta cleanliness', 'acid-insoluble ash', 'wholesale price', 'container load'];
const b2bHits = B2B.filter(p => new RegExp(p.trim(), 'i').test(low));
if (b2bHits.length) warn.push(`NGON NGU B2B lot vao bai B2C: ${b2bHits.join(', ')}`);

// ---- 3. PHU SECONDARY KEYWORD ----
const STOP = new Set(['of','the','and','in','with','for','a','an','to','types','type','kinds','kind','different']);
const secondaries = String(brief.secondary || '').split(/[,;\n|]/).map(s => s.trim()).filter(Boolean);
const missing = [];
for (const kw of secondaries) {
  const words = kw.toLowerCase().split(/\s+/).filter(w => w.length > 2 && !STOP.has(w));
  if (!words.length) continue;
  if (words.filter(w => low.includes(w)).length / words.length < 0.6) missing.push(kw);
}
const coverPct = secondaries.length
  ? Math.round(((secondaries.length - missing.length) / secondaries.length) * 100) : 100;
if (missing.length) warn.push(`Secondary chua phu (${coverPct}%): ${missing.join(' / ')}`);

// ---- 4. ANH ----
const imgCount = (bodyOnly.match(/<img /gi) || []).length;
if (/image|picture|photo/i.test(String(brief.secondary || '')) && imgCount === 0) {
  warn.push('Secondary co keyword "images" nhung bai khong co the <img> nao');
}
const badAlt = (bodyOnly.match(/<img (?![^>]*alt="[^"]{15,})[^>]*>/gi) || []).length;
if (imgCount && badAlt) warn.push(`${badAlt}/${imgCount} anh thieu alt text mo ta`);

// ---- 5. BANG SO SANH ----
const tableCount = (html.match(/<table/gi) || []).length;
let deadCols = [], emptyCellPct = 0, hedgeCells = 0;
if (tableCount === 0) {
  warn.push('KHONG CO BANG SO SANH - bai commercial khong dat');
} else {
  const tbody = html.match(/<tbody>[\s\S]*?<\/tbody>/i)?.[0] || '';
  const rows = [...tbody.matchAll(/<tr>([\s\S]*?)<\/tr>/g)]
    .map(m => [...m[1].matchAll(/<td>([\s\S]*?)<\/td>/g)]
      .map(c => c[1].replace(/<[^>]*>/g, '').trim()));
  if (rows.length < 3) warn.push(`Bang chi co ${rows.length} dong - can it nhat 3`);

  // rao chan bat dinh nhoi trong o
  const HEDGE = /(may vary|can vary|ranges? (differ|vary)|depending on (testing|sample|origin|batch)|approximate|varies by)/i;
  hedgeCells = rows.flat().filter(c => HEDGE.test(c)).length;
  if (hedgeCells >= 3) {
    warn.push(`${hedgeCells} o bang co rao chan kieu "may vary" - chuyen thanh 1 cau duoi bang`);
  }

  if (rows.length > 1) {
    const headers = [...(html.match(/<thead>[\s\S]*?<\/thead>/i)?.[0] || '')
      .matchAll(/<th>([\s\S]*?)<\/th>/g)].map(h => h[1].replace(/<[^>]*>/g, '').trim());
    const nCol = Math.max(...rows.map(r => r.length));
    for (let c = 1; c < nCol; c++) {
      const col = rows.map(r => (r[c] ?? '').toLowerCase());
      if (new Set(col).size === 1 && col[0] !== '') deadCols.push(headers[c] || `cot ${c + 1}`);
    }
    if (deadCols.length) warn.push(`Cot bang khong so sanh duoc: ${deadCols.join(', ')}`);
    const cells = rows.flatMap(r => r.slice(1)).map(c => c.toLowerCase());
    const empty = cells.filter(c => !c || /^(not published|n\/a|-|\u2014)$/.test(c)).length;
    emptyCellPct = cells.length ? Math.round((empty / cells.length) * 100) : 0;
    if (emptyCellPct > 25) warn.push(`Bang rong ${emptyCellPct}% o`);
    if (CURRENCY.test(rows.flat().join(' '))) warn.push('Bang co gia theo tien te cu the - phai la muc gia tuong doi');
  }
}

// ---- 6. "not published" ----
const npCount = (low.match(/not published/g) || []).length;
if (npCount > 3) warn.push(`"not published" xuat hien ${npCount} lan (toi da 3)`);
if (/not published here/i.test(text)) warn.push('Con cum "not published here"');

// ---- 7. LINK ----
const linkCount = (bodyOnly.match(/<a [^>]*href=/gi) || []).length;
if (linkCount < 3) warn.push(`Chi co ${linkCount} link inline - can it nhat 3`);
if (/<(h2|h3|p)[^>]*>\s*(references?|sources?|citations?|further reading)\b/i.test(bodyOnly)) {
  warn.push('Co danh sach References/Sources - phai chuyen thanh link inline');
}
if (/https?:\/\//.test(bodyOnly.replace(/<a [^>]*>|<\/a>|href="[^"]*"|src="[^"]*"/g, ''))) {
  warn.push('Co URL tran trong body');
}

// ---- 8. MARKDOWN SOT / META-COMMENTARY ----
if (/!\[[^\]]*\]\(/.test(html)) warn.push('Con markdown anh chua render');
if (/(^|\n)\s*---\s*(\n|$)/.test(html)) warn.push('Con dau --- chua thanh <hr>');
const metaTalk = ['notes on sources', 'sources within cells', 'references include',
  'citations include', 'this article cites', 'the research above', 'as used in this article'];
const metaHits = metaTalk.filter(p => low.includes(p));
if (metaHits.length) warn.push(`Meta-commentary lot vao bai: ${metaHits.join(', ')}`);

// ---- 9. CAU MO DAU ----
const firstPara = bodyOnly.match(/<h2>[\s\S]*?<\/h2>\s*<p>([\s\S]*?)<\/p>/)?.[1]?.replace(/<[^>]*>/g, '') || '';
const firstSentence = firstPara.split(/(?<=\.)\s/)[0] || '';
if ((firstSentence.match(/;/g) || []).length >= 2) warn.push('Cau mo dau la chuoi ghep bang dau ;');
if (firstSentence.split(/\s+/).length > 45) warn.push(`Cau dau tien dai ${firstSentence.split(/\s+/).length} tu`);

// ---- 10. SO LIEU ----
const figuresGiven = (brief.decision_figures || []).length;
const numbersInBody = (text.match(/\b\d+(?:[.,]\d+)?\s*(?:%|mg\/kg|ppm|ppb|\bg\b|kg)/gi) || []).length;
if (figuresGiven === 0) warn.push('Facts C khong tim duoc so lieu nao - xem lai query trong Search Planner C');
else if (numbersInBody < 3) warn.push(`Brief co ${figuresGiven} so lieu nhung bai chi dung ${numbersInBody}`);

// ---- 11. GIONG BAN HANG / HEADING BAN / FAQ ----
const salesy = ['contact us', 'reach out to us', 'we offer', 'our products are', 'manufacturers like tmicorp'];
const salesHits = salesy.filter(p => low.includes(p));
if (salesHits.length) warn.push(`Giong ban hang: ${salesHits.join(', ')}`);

const dirty = [];
for (const m of html.matchAll(/<h[23]>([^<]+)<\/h[23]>/g)) {
  if (/\((?:render|use|using|target|insert|include|note|format|framing|keyword|placement|depth)\b[^)]*\)/i.test(m[1])) dirty.push(m[1].trim());
}
if (dirty.length) warn.push(`Heading co chi dan lot: ${dirty.join(' | ')}`);

const faqs = [];
for (const m of html.matchAll(/<h3>([^<]*\?)<\/h3>\s*<p>([\s\S]*?)<\/p>/g)) {
  faqs.push({ q: m[1].trim(), a: m[2].replace(/<[^>]*>/g, '').trim() });
}
if (faqs.length < 4) warn.push(`Chi tim thay ${faqs.length} FAQ - can 4-6`);

// ---- disclaimer khi co benefits ----
const disclaimer = /benefit|antioxidant|blood sugar|anti-inflammat/i.test(text)
  ? '<div class="disclaimer"><p><em>This article is for general information only and is not medical advice. Talk to a qualified healthcare professional about your own situation.</em></p></div>'
  : '';

const eeatTop = `<div class="post-meta"><p><strong>By ${author}</strong> | Last updated: ${today}</p></div>`;

const ld = [{
  '@context': 'https://schema.org', '@type': 'Article',
  headline: meta.title_seo || chosenTitle,
  description: meta.meta_description || '',
  datePublished: today, dateModified: today,
  author: { '@type': 'Organization', name: author },
  publisher: {
    '@type': 'Organization',
    name: 'TMICORP - Toan My International Trading Investment JSC.',
    url: 'https://tmicorpgroup.com',
    address: { '@type': 'PostalAddress', addressLocality: 'Hanoi', addressCountry: 'VN' },
  },
}];

if (faqs.length > 0) {
  ld.push({
    '@context': 'https://schema.org', '@type': 'FAQPage',
    mainEntity: faqs.map(f => ({
      '@type': 'Question', name: f.q,
      acceptedAnswer: { '@type': 'Answer', text: f.a },
    })),
  });
}

const finalHtml = [eeatTop, disclaimer, html,
  `<script type="application/ld+json">${JSON.stringify(ld)}</script>`].filter(Boolean).join('\n');

const BLOCKERS = /KHONG CO BANG SO SANH|link inline|URL tran|References\/Sources|Bang rong|NGON NGU B2B|CO GIA THEO MOT LOAI TIEN TE|DAN CO QUAN QUOC GIA|NEU TEN CHUOI BAN LE/i;
const blockers = warn.filter(w => BLOCKERS.test(w));

return [{
  json: {
    html: finalHtml, flow: 'commercial-b2c',
    chosen_title: chosenTitle,
    slug: meta.slug || '', title_seo: meta.title_seo || '',
    meta_description: meta.meta_description || '',
    tags: meta.tags || '', excerpt: meta.excerpt || '',
    word_count: text.split(/\s+/).filter(Boolean).length,
    secondary_coverage_pct: coverPct,
    secondary_missing: missing.join(' / ') || 'none',
    image_count: imgCount,
    table_count: tableCount,
    dead_columns: deadCols.join(', ') || 'none',
    hedge_cells: hedgeCells,
    empty_cell_pct: emptyCellPct,
    link_count: linkCount,
    not_published_count: npCount,
    faq_count: faqs.length,
    figures_available: figuresGiven,
    figures_used_approx: numbersInBody,
    row_number: brief.row_number,
    qa_warnings: warn.length ? warn.join(' | ') : 'OK',
    qa_blockers: blockers.length ? blockers.join(' | ') : 'none',
    qa_pass: blockers.length === 0,
  }
}];

