// Tach ke hoach search cua planner thanh 1 item / 1 query.

const plan = $input.first().json.output ?? $input.first().json;
const row  = $('Prep Commercial').first().json;

const queries = Array.isArray(plan.queries) ? plan.queries : [];
const VALID = ['serp', 'option', 'attribute', 'safety', 'price', 'local'];
const seen = new Set();
const out = [];

for (const q of queries) {
  const query = String(q?.query || '').trim();
  if (!query) continue;

  let purpose = String(q?.purpose || 'attribute').trim().toLowerCase();
  if (!VALID.includes(purpose)) purpose = 'attribute';

  const key = query.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);

  out.push({ json: {
    ...row,
    query,
    purpose,
    product_form:     plan.product_form     || 'other',
    in_range:         plan.in_range !== false,
    compared_options: plan.compared_options || [],
    keyword_topics:   plan.keyword_topics   || [],
    dropped_keywords: plan.dropped_keywords || [],
    table_columns:    plan.table_columns    || [],
    buying_checklist: plan.buying_checklist || [],
    plan_reasoning:   plan.reasoning        || '',
  }});
}

if (out.length === 0) {
  throw new Error('Search Planner C khong tra ve query nao.');
}
if (!out.some(i => i.json.purpose === 'serp')) out[0].json.purpose = 'serp';

return out;

// Chuan hoa dau cau TRUOC khi doi sang HTML.
// Bo em dash (U+2014) va en dash (U+2013).
// GIU NGUYEN hyphen thuong trong tu ghep: low-calorie, nutrient-rich...
function cleanTypography(input) {
  let s = String(input || '');
  const keep = [];

  // Bao ve URL trong markdown link va image: ](...)
  s = s.replace(/\]\([^)\s]+\)/g, (m) => '\u0000' + (keep.push(m) - 1) + '\u0000');

  s = s
    .replace(/(\d)\s*\u2013\s*(\d)/g, '$1-$2')   // 3-5 days
    .replace(/(\S)\u2013(\S)/g, '$1-$2')          // vitamin C-driven
    .replace(/\s*\u2013\s*/g, ', ')               // en dash con lai
    .replace(/\s*\u2014\s*/g, ', ')               // em dash -> dau phay
    .replace(/[\u201C\u201D]/g, '"')
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/\u2026/g, '...')
    .replace(/\u00A0/g, ' ')
    .replace(/,\s*,+/g, ',')
    .replace(/[ \t]+,/g, ',')
    .replace(/,\s*([.;:!?])/g, '$1');

  return s.replace(/\u0000(\d+)\u0000/g, (_, i) => keep[i]);
}

return $input.all().map((item) => ({
  json: { ...item.json, output: cleanTypography(item.json.output) }
}));

